const disponiveis = [];
const indisponiveis = [];
ordenados.forEach(function (p) {
  const d = fatos[p.tmdb_id];
  if (!d) return;
  const filme = montar(d, corrigirAcentuacao(p.reason));
  if (filme.providers.length > 0) disponiveis.push(filme);
  else indisponiveis.push(filme);
