// Fatos crus, no formato EXATO da tabela movies: guarda o PATH, nunca a URL.
// Tamanho de imagem (w342, w500) e decisao de apresentacao e e montado em
// 'Montar resposta'; congelar a URL no banco significa reescrever a tabela
// inteira so para trocar de tamanho.
// Mesmo filtro de 'Montar resposta' e 'Preparar registro': a sentinela
// { vazio: true } de 'Escolher correspondencia' nao e filme. O IF 'Achou
// algum?' ja impede que ela chegue ate aqui; o filtro fica porque este laco
// pareia casados[i] com fichas[i] POR INDICE, e um item a mais no comeco
// desalinharia todos os pares em silencio.
const casados = $('Escolher correspondencia').all()
  .map(function (i) { return i.json; })
  .filter(function (c) { return c && c.tmdbId != null; });
const fichas = $('TMDB detalhes').all().map(function (i) { return i.json; });
const notas = $input.all().map(function (i) { return i.json; });

function ausente(v) { return v == null || v === 'N/A' || v === ''; }
function numero(v) {
  if (ausente(v)) return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}

const linhas = [];
for (let i = 0; i < casados.length; i++) {
  const d = fichas[i];
  if (!d || !d.id) continue;
  const o = notas[i] || {};
  const temNota = o.Response === 'True';

  const creditos = d.credits || {};
  const equipe = Array.isArray(creditos.crew) ? creditos.crew : [];
  const elenco = Array.isArray(creditos.cast) ? creditos.cast : [];
  const diretor = equipe.find(function (c) { return c.job === 'Director'; });

  const lancamentos = (d.release_dates && d.release_dates.results) || [];
  const br = lancamentos.find(function (r) { return r.iso_3166_1 === 'BR'; });
  const cert = ((br && br.release_dates) || [])
    .map(function (r) { return r.certification; })
    .find(function (c) { return c; });

  const videos = (d.videos && d.videos.results) || [];
  const trailer = videos.find(function (v) { return v.site === 'YouTube' && v.type === 'Trailer'; })
    || videos.find(function (v) { return v.site === 'YouTube'; });

  const logos = (d.images && d.images.logos) || [];
  const logo = logos.find(function (l) { return l.iso_639_1 === 'pt'; }) || logos[0];

  const onde = ((d['watch/providers'] || {}).results || {}).BR || {};
  const provedores = [];
  // Os tipos ESPELHAM ProviderType em src/lib/types.ts. Gravar em portugues
  // aqui quebra todo filtro escrito contra o contrato — e quebra em SILENCIO,
  // porque o campo existe, so nunca casa. 'free' e 'ads' entram porque filme
  // gratuito com anuncio tambem e uma resposta valida para 'onde assistir'.
  ['flatrate', 'free', 'ads', 'rent', 'buy'].forEach(function (tipo) {
    (onde[tipo] || []).forEach(function (p) {
      provedores.push({ type: tipo, name: p.provider_name, logo_path: p.logo_path || null });
    });
  });

  linhas.push({
    tmdb_id: d.id,
    imdb_id: (d.external_ids && d.external_ids.imdb_id) || null,
    title: d.title || casados[i].title,
    original_title: d.original_title || null,
    release_year: d.release_date ? Number(d.release_date.slice(0, 4)) : null,
    tagline: d.tagline || null,
    overview: d.overview || null,
    poster_path: d.poster_path || null,
    backdrop_path: d.backdrop_path || null,
    logo_path: (logo && logo.file_path) || null,
    rating: typeof d.vote_average === 'number' ? Number(d.vote_average.toFixed(1)) : null,
    vote_count: d.vote_count == null ? null : d.vote_count,
    imdb_rating: temNota ? numero(o.imdbRating) : null,
    imdb_votes: temNota ? numero(o.imdbVotes) : null,
    awards: temNota && !ausente(o.Awards) ? o.Awards : null,
    runtime: d.runtime || null,
    genres: (d.genres || []).map(function (g) { return g.name; }),
    keywords: (((d.keywords || {}).keywords) || []).slice(0, 12).map(function (k) { return k.name; }),
    original_language: d.original_language || null,
    spoken_languages: (d.spoken_languages || []).map(function (l) { return l.name; }),
    age_rating: cert || null,
    director: (diretor && diretor.name) || null,
    cast_members: elenco.slice(0, 10).map(function (a) {
      return { name: a.name, character: a.character || null, profile_path: a.profile_path || null };
    }),
    crew_members: equipe.filter(function (c) {
      return ['Director', 'Screenplay', 'Writer', 'Director of Photography', 'Original Music Composer'].indexOf(c.job) !== -1;
    }).slice(0, 8).map(function (c) {
      return { name: c.name, role: c.job, profile_path: c.profile_path || null };
    }),
    collection_name: (d.belongs_to_collection && d.belongs_to_collection.name) || null,
    similar_movies: (((d.recommendations || {}).results) || []).slice(0, 8).map(function (r) {
      return {
        tmdb_id: r.id, title: r.title,
        year: r.release_date ? Number(r.release_date.slice(0, 4)) : null,
        poster_path: r.poster_path || null, backdrop_path: r.backdrop_path || null,
      };
    }),
    providers: provedores,
    trailer_key: (trailer && trailer.key) || null,
  });
}
// Chegar aqui com zero linhas significa que os titulos JA tinham sido
// confirmados no TMDB ('Escolher correspondencia' passou) e mesmo assim o
// enriquecimento nao produziu nada — ou seja, o TMDB caiu no meio do caminho.
// Upstream fora, nao defeito nosso: o 'Responder erro' devolve 502 para este
// no. Ate 09/09/2026 este throw pendurava o webhook ate o teto de 45 s do BFF.
//
// A mensagem e o que o usuario le, e o codigo vem do NOME DO NO — nao do
// texto: medido na execucao 2359, o no Code reescreve a mensagem do throw.
if (!linhas.length) {
  throw new Error('Nao consegui buscar os dados dos filmes agora. Tente de novo em instantes.');
}

// Um unico item com o array dentro: o no Postgres roda a query uma vez so,
// com um parametro jsonb, em vez de uma query por filme.
return [{ json: { linhas: linhas } }];

const entrada = $('Validar entrada').first().json;
// Corrige por TABELA palavras que o modelo escreve sem acento no `reason`.
// Medido em 09/09/2026: 8/8, 5/8 e 1/8 sem acento em tres baterias da mesma
// intencao. Reforcar o prompt (a v5 ja fez isso) e trocar de modelo (o
// 3.1-flash-lite foi escolhido por latencia, 03/09/2026) foram descartados por
// medicao. So entram palavras cuja forma sem acento NAO existe como outra
// palavra valida em portugues — "atmosfera" nao leva acento e por isso nao
// esta aqui. Espelha n8n/logica/corrigir-acentuacao.js.
//
// Aplicado ANTES de persistir: sem isto, um acerto de cache voltaria a servir
// o texto sem acento que o curador gerou antes desta correcao existir.
var LEXICO_ACENTUACAO = {
  nao: "não",
  psicologico: "psicológico",
  decada: "década",
  japones: "japonês",
  historia: "história",
  familia: "família",
  tragedia: "tragédia",
  solidao: "solidão",
};
function corrigirAcentuacao(texto) {
  var s = String(texto == null ? "" : texto);
  return s.replace(/[A-Za-zÀ-ÿ]+/g, function (palavra) {
    var certa = LEXICO_ACENTUACAO[palavra.toLowerCase()];
    if (!certa) return palavra;
    if (palavra[0] === palavra[0].toUpperCase()) {
      return certa[0].toUpperCase() + certa.slice(1);
    }
    return certa;
  });
}
const resp = $('Montar resposta').first().json;
const l1 = $('Cache L1').all();
const doCache = l1.length > 0 && l1[0].json && Array.isArray(l1[0].json.picks) && l1[0].json.picks.length > 0;

let picks;
if (doCache) {
  picks = l1[0].json.picks;
} else {
  // Mesmo filtro de 'Montar resposta': a sentinela { vazio: true } de
  // 'Escolher correspondencia' nao e filme e nao pode virar pick.
  picks = $('Escolher correspondencia').all()
    .map(function (i) { return i.json; })
    .filter(function (c) { return c && c.tmdbId != null; })
    .map(function (c) {
      return { tmdb_id: c.tmdbId, reason: corrigirAcentuacao(c.reason), rank: c.rank };
    });
}

// searches.request_id e uuid NOT NULL. O BFF sempre manda um; chamada de
// teste feita na mao, nao. Marcar com o uuid nulo e mais honesto que
// derrubar a gravacao de telemetria por causa de um curl.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const requestId = UUID.test(entrada.requestId || '')
  ? entrada.requestId
  : '00000000-0000-0000-0000-000000000000';

return [{ json: {
  queryHash: $('Hash').first().json.queryHash,
  queryText: entrada.preferences,
  queryNorm: entrada.queryNorm,
  limitN: entrada.limit,
  promptVersion: entrada.promptVersion,
  picks: picks,
  notFound: resp.notFound || [],
  collectionTitle: resp.collectionTitle,
  // ATENCAO: este null NAO e so telemetria, e contrato.
  //
  // O ON CONFLICT do no 'Gravar L1' usa `EXCLUDED.model_used IS NULL` para
  // saber se a gravacao veio do cache ou do curador. NULL significa "nao
  // chamei modelo nenhum", e o SQL entao preserva picks, collection_title e
  // created_at, contando so mais um hit. Preencher isto num acerto de cache
  // faria toda leitura renovar o created_at, e a curadoria nunca envelheceria.
  // Trocar o 'gemini' por null faria o contrario: a entrada expirada nunca se
  // recuperaria, que era exatamente o defeito consertado em 03/09/2026.
  //
  // O valor da string em si nao importa para o SQL, so o null-ou-nao.
  modelUsed: doCache ? null : 'gemini',
  cacheHit: !!doCache,
  // 'human' | 'robot', decidido pelo 'Validar entrada' a partir de body.source.
  // So a telemetria em 'searches' le isto (5.3) — search_cache continua sem
  // marca, de proposito: a curadoria de um recorte do robo serve normalmente
  // se uma pessoa buscar as mesmas palavras depois.
  source: entrada.source,
  // Lido pelo IF 'Vale cachear?', que decide se 'Gravar L1' roda. Zero filmes
  // NAO pode entrar no search_cache: 'Cache L1' nao filtra por picks vazio,
  // mas 'Tem cache?' exige picks notEmpty — a linha nunca serviria de cache e
  // ainda assim ocuparia o query_hash por 30 dias, mandando toda busca daquela
  // consulta pelo curador de novo. Cache miss permanente COM custo de LLM, que
  // e o pior dos dois mundos e foi o defeito consertado em 03/09/2026 por
  // outro caminho. Zero confirmados costuma ser transitorio (TMDB fora, uma
  // curadoria ruim): a proxima busca merece tentar de novo, fresca.
  //
  // A telemetria em 'searches' continua gravando normalmente — e justamente
  // dela que sai a contagem de movie_count = 0.
  valeCachear: (resp.movies || []).length > 0,
  movieCount: (resp.movies || []).length,
  notFoundCount: (resp.notFound || []).length,
  latencyMs: Date.now() - Number(entrada.inicio || Date.now()),
  requestId: requestId,
} }]
